from typing import List, Optional
from pydantic import BaseModel, Field

from app.schemas.task import TaskPriority


class TaskSuggestionItem(BaseModel):
    """Structured task suggestion generated by the AI service."""

    title: str = Field(..., min_length=1, max_length=150, description="Task title")
    description: str = Field(default="", max_length=1000, description="Detailed actionable description")
    linked_goal_id: Optional[str] = Field(None, description="Optional user goal ID reference")
    linked_milestone_id: Optional[str] = Field(None, description="Optional user milestone ID reference")
    priority: TaskPriority = Field(default=TaskPriority.MEDIUM, description="Task priority")
    estimated_duration: int = Field(default=30, ge=5, le=480, description="Duration in minutes (5 to 480)")
    suggested_date: Optional[str] = Field(None, pattern=r"^\d{4}-\d{2}-\d{2}$", description="Suggested execution date (YYYY-MM-DD)")
    suggested_deadline: Optional[str] = Field(None, description="Suggested completion deadline")
    short_explanation: str = Field(..., max_length=500, description="Why this task is proposed and aligns with goals")


class DailyTaskSuggestionsRequest(BaseModel):
    """Request payload for daily task suggestions."""

    target_date: Optional[str] = Field(None, pattern=r"^\d{4}-\d{2}-\d{2}$", description="Target date (defaults to today)")
    available_time_minutes: Optional[int] = Field(None, ge=15, le=1440, description="Minutes available for tasks today")
    preferences: Optional[str] = Field(None, max_length=500, description="User guidance or preferences for today")
    focus_goal_ids: Optional[List[str]] = Field(default_factory=list, max_length=5, description="Specific goals to prioritize")
    timezone: Optional[str] = Field("UTC", max_length=50, description="User configured IANA timezone")


class DailyTaskSuggestionsResponse(BaseModel):
    """Response containing AI-generated daily task suggestions."""

    target_date: str
    available_time_minutes: int
    total_suggested_duration: int
    suggestions: List[TaskSuggestionItem]
    explanation: str
    provider: str
    model: str


class RevisedScheduleRequest(BaseModel):
    """Request payload for generating a revised schedule when priorities or time change."""

    target_date: Optional[str] = Field(None, pattern=r"^\d{4}-\d{2}-\d{2}$", description="Target date to revise")
    available_time_minutes: Optional[int] = Field(None, ge=15, le=1440, description="Updated available minutes")
    reasons: Optional[str] = Field(None, max_length=500, description="Reasons for rescheduling (e.g. interruption, fatigue)")
    timezone: Optional[str] = Field("UTC", max_length=50, description="User configured IANA timezone")


class RevisedScheduleResponse(BaseModel):
    """Response containing proposed schedule revisions with user confirmation required."""

    target_date: str
    available_time_minutes: int
    total_planned_duration: int
    scheduled_tasks: List[TaskSuggestionItem]
    postponed_proposals: List[TaskSuggestionItem]
    explanation: str
    requires_user_confirmation: bool = True
    provider: str
    model: str


class RecoveryPlanRequest(BaseModel):
    """Request payload to initiate Recovery Mode for overdue or accumulated work."""

    current_date: Optional[str] = Field(None, pattern=r"^\d{4}-\d{2}-\d{2}$", description="Current reference date")
    available_daily_minutes: Optional[int] = Field(None, ge=30, le=1440, description="Daily available capacity for catching up")
    user_note: Optional[str] = Field(None, max_length=500, description="Context regarding overdue state or bottlenecks")
    timezone: Optional[str] = Field("UTC", max_length=50, description="User configured IANA timezone")


class RecoveryPlanResponse(BaseModel):
    """Response containing realistic recovery plan with priority adjustments and breakdown proposals."""

    overdue_tasks_count: int
    overdue_task_ids: List[str]
    proposed_priorities: List[TaskSuggestionItem]
    rescheduling_proposals: List[TaskSuggestionItem]
    complex_tasks_breakdowns: List[TaskSuggestionItem]
    action_plan_summary: str
    preserves_history: bool = True
    requires_user_confirmation: bool = True
    provider: str
    model: str


class ExplainGoalProgressRequest(BaseModel):
    """Request payload to analyze and explain goal progress trends."""

    goal_id: Optional[str] = Field(None, description="Optional single goal ID; analyzes overall goals if omitted")
    timezone: Optional[str] = Field("UTC", max_length=50, description="User configured IANA timezone")


class ExplainGoalProgressResponse(BaseModel):
    """Response containing qualitative analysis and actionable recommendations for goals."""

    goal_id: Optional[str] = None
    overall_status: str
    completion_percentage: float
    insights: List[str]
    strengths: List[str]
    bottlenecks: List[str]
    recommended_next_actions: List[TaskSuggestionItem]
    explanation: str
    provider: str
    model: str


class TaskBreakdownRequest(BaseModel):
    """Request payload to decompose a large or complex task into actionable subtasks."""

    task_title: Optional[str] = Field(None, max_length=200, description="Title of the task to break down")
    task_description: Optional[str] = Field(None, max_length=1000, description="Context or requirements")
    task_id: Optional[str] = Field(None, description="Existing task ID if already tracked in the database")
    goal_id: Optional[str] = Field(None, description="Parent goal ID if applicable")
    milestone_id: Optional[str] = Field(None, description="Parent milestone ID if applicable")
    max_subtasks: int = Field(5, ge=2, le=10, description="Maximum number of subtasks to generate")


class TaskBreakdownResponse(BaseModel):
    """Response containing decomposed subtasks for user confirmation."""

    original_task_title: str
    linked_goal_id: Optional[str] = None
    linked_milestone_id: Optional[str] = None
    subtasks: List[TaskSuggestionItem]
    total_estimated_duration: int
    explanation: str
    provider: str
    model: str
